/**
 * Club nights synced from https://pacha.com/events (`initialEvents` payload).
 * Regenerate: curl -sL 'https://pacha.com/events' -o /tmp/pacha-events-page.html
 * then run the scrape script in repo or re-export from live JSON.
 *
 * `PACHA_EVENTS` is a prototype subset spread across May–Oct (see
 * `PACHA_EVENTS_PROTOTYPE_TOTAL`). Set it to `PACHA_EVENTS_SOURCE.length` for
 * the full scraped list.
 */
export type PachaEventRow = {
  id: string
  title: string
  venue: string
  date: string
  month: 'may' | 'jun' | 'jul' | 'aug' | 'sep' | 'oct'
  price: number
  vipPrice: number
  image: string
  doors?: string
  lineup?: string
  soldOut?: boolean
}

const SEASON_MONTHS: PachaEventRow['month'][] = ['may', 'jun', 'jul', 'aug', 'sep', 'oct']

/** Prototype grid size: spread evenly across `SEASON_MONTHS` (first N chronologically per month). */
export const PACHA_EVENTS_PROTOTYPE_TOTAL = 18

function pickEvenlyAcrossMonths(source: PachaEventRow[], total: number): PachaEventRow[] {
  const n = SEASON_MONTHS.length
  const capped = Math.max(0, Math.floor(total))
  const base = Math.floor(capped / n)
  const extra = capped % n
  const buckets = new Map<PachaEventRow['month'], PachaEventRow[]>()
  for (const m of SEASON_MONTHS) buckets.set(m, [])
  for (const e of source) {
    buckets.get(e.month)?.push(e)
  }
  const out: PachaEventRow[] = []
  SEASON_MONTHS.forEach((m, i) => {
    const take = base + (i < extra ? 1 : 0)
    out.push(...(buckets.get(m) ?? []).slice(0, take))
  })
  return out
}

